import{_ as r,a0 as u,w as s,s as i,I as l,x as o,a1 as p,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"我買了一台 Linux 筆記本 | LCTT x X-CMD","titleTemplate":false,"description":"我買了一台 Linux 筆記本 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我買了一台 Linux 筆記本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我買了一台 Linux 筆記本 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190719 Buying a Linux-ready laptop","title":"我買了一台 Linux 筆記本","tag":"201910","desc":""},"relativePath":"201910/20190719 Buying a Linux-ready laptop.md","filePath":"[post].md"}'),a={name:"201910/20190719 Buying a Linux-ready laptop.md"};function x(m,t,f,T,L,C){const e=u("Link");return s(),i("div",null,[t[32]||(t[32]=l("h1",{id:"我買了一台-linux-筆記本",tabindex:"-1"},[o("我買了一台 Linux 筆記本 "),l("a",{class:"header-anchor",href:"#我買了一台-linux-筆記本","aria-label":"Permalink to “我買了一台 Linux 筆記本”"},"​")],-1)),t[33]||(t[33]=l("blockquote",null,[l("p",null,"Tuxedo 讓買一台開箱即用的 Linux 筆記本變得容易。")],-1)),t[34]||(t[34]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/201910/08/133924vnmbklqh5jkshkmj.jpg",alt:""})],-1)),l("p",null,[t[3]||(t[3]=o("最近，我開始使用我買的 Linux 筆記本計算機 Tuxedo Book BC1507。十年前，如果有人告訴我，十年後我可以從 ",-1)),p(e,{href:"https://system76.com/"},{default:n(()=>[...t[0]||(t[0]=[o("System76",-1)])]),_:1}),t[4]||(t[4]=o("、",-1)),p(e,{href:"https://slimbook.es/en/"},{default:n(()=>[...t[1]||(t[1]=[o("Slimbook",-1)])]),_:1}),t[5]||(t[5]=o(" 和 ",-1)),p(e,{href:"https://www.tuxedocomputers.com/"},{default:n(()=>[...t[2]||(t[2]=[o("Tuxedo",-1)])]),_:1}),t[6]||(t[6]=o(" 等公司購買到高質量的“企鵝就緒”的筆記本電腦。我可能會發笑。好吧，現在我也在笑，但是很開心！",-1))]),l("p",null,[t[9]||(t[9]=o("除了為免費/自由開源軟件（FLOSS）設計計算機之外，這三家公司最近",-1)),p(e,{href:"https://www.tuxedocomputers.com/en/Infos/News/Tuxedo-Computers-stands-for-Free-Software-and-Security-.tuxedo"},{default:n(()=>[...t[7]||(t[7]=[o("宣佈",-1)])]),_:1}),t[10]||(t[10]=o("都試圖通過切換到",-1)),p(e,{href:"https://coreboot.org/"},{default:n(()=>[...t[8]||(t[8]=[o("Coreboot",-1)])]),_:1}),t[11]||(t[11]=o("來消除專有的 BIOS 軟件。",-1))]),t[35]||(t[35]=d('<h3 id="買一台" tabindex="-1">買一台 <a class="header-anchor" href="#買一台" aria-label="Permalink to “買一台”">​</a></h3><p>Tuxedo Computers 是一家德國公司，生產支持 Linux 的筆記本電腦。實際上，如果你要使用其他的操作系統，則它的價格會更高。</p><p>購買他們的計算機非常容易。Tuxedo 提供了許多付款方式：不僅包括信用卡，而且還包括 PayPal 甚至銀行轉帳（LCTT 譯註：我們需要支付寶和微信支付……此外，要國際配送，還需要支付運輸費和清關費用等）。只需在 Tuxedo 的網頁上填寫銀行轉帳表格，公司就會給你發送銀行信息。</p><p>Tuxedo 可以按需構建每台計算機，只需選擇基本模型並瀏覽下拉菜單以選擇不同的組件，即可輕鬆準確地選擇所需內容。頁面上有很多信息可以指導你進行購買。</p><p>如果你選擇的 Linux 發行版與推薦的發行版不同，則 Tuxedo 會進行“網絡安裝”，因此請準備好網絡電纜以完成安裝，也可以將你首選的鏡像文件刻錄到 USB 盤上。我通過外部 DVD 閲讀器來安裝刻錄了 openSUSE Leap 15.1 安裝程序的 DVD，但是你可用你自己的方式。</p><p>我選擇的型號最多可以容納兩個磁盤：一個 SSD，另一個可以是 SSD 或常規硬盤。由於已經超出了我的預算，因此我決定選擇傳統的 1TB 磁盤並將 RAM 增加到 16GB。該處理器是具有四個內核的第八代 i5。我選擇了背光西班牙語鍵盤、1920×1080/96dpi 屏幕和 SD 卡讀卡器。總而言之，這是一個很棒的系統。</p><p>如果你對默認的英語或德語鍵盤感覺滿意，甚至可以要求在 Meta 鍵上印上一個企鵝圖標！我需要的西班牙語鍵盤則不提供此選項。</p><h3 id="收貨並開箱使用" tabindex="-1">收貨並開箱使用 <a class="header-anchor" href="#收貨並開箱使用" aria-label="Permalink to “收貨並開箱使用”">​</a></h3><p>付款完成後僅六個工作日，完好包裝的計算機就十分安全地到達了我家。打開計算機包裝並解鎖電池後，我準備好開始浪了。</p><p><img src="https://opensource.com/sites/default/files/uploads/tuxedo-600_0.jpg" alt="Tuxedo Book BC1507" title="Tuxedo Book BC1507"></p><p><em>我的（物理）桌面上的新玩具。</em></p><p>該電腦的設計確實很棒，而且感覺紮實。即使此型號的外殼不是鋁製的（LCTT 譯註：他們有更好看的鋁製外殼的型號），也可以保持涼爽。風扇真的很安靜，氣流像許多其他筆記本電腦一樣導向後邊緣，而不是流向側面。電池可提供數小時的續航時間。BIOS 中的一個名為 FlexiCharger 的選項會在達到一定百分比後停止為電池充電，因此在插入電源長時間工作時，無需卸下電池。</p><p>鍵盤真的很舒適，而且非常安靜。甚至觸摸板按鍵也很安靜！另外，你可以輕鬆調整背光鍵盤上的光強度。</p><p>最後，很容易訪問筆記本電腦中的每個組件，因此可以毫無問題地對計算機進行更新或維修。Tuxedo 甚至送了幾個備用螺絲！</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>經過一個月的頻繁使用，我對該系統感到非常滿意。它完全滿足了我的要求，並且一切都很完美。</p><p>因為它們通常是高端系統，所以包含 Linux 的計算機往往比較昂貴。如果你將 Tuxedo 或 Slimbook 電腦的價格與更知名品牌的類似規格的價格進行比較，價格相差無幾。如果你想要一台使用自由軟件的強大系統，請毫不猶豫地支持這些公司：他們所提供的物有所值。</p><p>請在評論中讓我們知道你在 Tuxedo 和其他“企鵝友好”公司的經歷。</p><hr>',19)),l("p",null,[t[14]||(t[14]=o("本文基於 Ricardo 的Blog ",-1)),p(e,{href:"https://frommindtotype.wordpress.com/"},{default:n(()=>[...t[12]||(t[12]=[o("From Mind to Type",-1)])]),_:1}),t[15]||(t[15]=o(" 上發表的“ ",-1)),p(e,{href:"https://frommindtotype.wordpress.com/2019/06/17/my-new-penguin-ready-laptop-tuxedo-book-bc1507/"},{default:n(()=>[...t[13]||(t[13]=[o("我的新企鵝筆記本電腦：Tuxedo-Book-BC1507",-1)])]),_:1}),t[16]||(t[16]=o("”。",-1))]),t[36]||(t[36]=l("hr",null,null,-1)),l("p",null,[t[18]||(t[18]=o("via: ",-1)),p(e,{href:"https://opensource.com/article/19/7/linux-laptop"},{default:n(()=>[...t[17]||(t[17]=[o("https://opensource.com/article/19/7/linux-laptop",-1)])]),_:1})]),l("p",null,[t[23]||(t[23]=o("作者：",-1)),p(e,{href:"https://opensource.com/users/rgb-es"},{default:n(()=>[...t[19]||(t[19]=[o("Ricardo Berlasso",-1)])]),_:1}),t[24]||(t[24]=o(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[20]||(t[20]=[o("lujun9972",-1)])]),_:1}),t[25]||(t[25]=o(" 譯者：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[21]||(t[21]=[o("wxy",-1)])]),_:1}),t[26]||(t[26]=o(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[22]||(t[22]=[o("wxy",-1)])]),_:1})]),l("p",null,[t[29]||(t[29]=o("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[27]||(t[27]=[o("LCTT",-1)])]),_:1}),t[30]||(t[30]=o(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:n(()=>[...t[28]||(t[28]=[o("Linux中國",-1)])]),_:1}),t[31]||(t[31]=o(" 榮譽推出",-1))])])}const S=r(a,[["render",x]]);export{B as __pageData,S as default};
